const otcState={module:null,activeRun:null,pollTimer:null,resultSummary:null,product:null,template:null,productTemplate:null,ledgerSort:'start_date',ledgerSortDir:'desc',ledgerFilters:{},filterOpen:false,llmStatus:null,fieldAudit:null,pricing:null,pricingRun:null,pricingPollTimer:null,pricingSourceId:null};

function installOtcNavigation(){const risk=document.querySelector('.dash-nav[data-page="risk"]');if(risk&&!document.querySelector('.dash-nav[data-page="otc-derivatives"]'))risk.insertAdjacentHTML('beforebegin','<button class="dash-nav" data-page="otc-derivatives" onclick="dashGo(\'otc-derivatives\',false,\'backtest\')"><i>⌁</i><span>场外衍生品</span></button>');const content=document.querySelector('.dash-content');if(content&&!document.getElementById('dashViewotc-derivatives'))content.insertAdjacentHTML('beforeend','<section class="dash-view" data-page="otc-derivatives" id="dashViewotc-derivatives"><div id="dashOtcDerivatives"></div></section>');const view=document.getElementById('dashViewotc-derivatives');if(view&&!document.getElementById('dashOtcDerivatives'))view.innerHTML='<div id="dashOtcDerivatives"></div>';documentOtcChange()}
function documentOtcChange(){const cards=document.querySelectorAll('.info-card'),method=cards[0]&&cards[0].querySelector('.info-body'),commands=cards[1]&&cards[1].querySelector('.command-doc');if(method&&!document.getElementById('otcHelpNote'))method.insertAdjacentHTML('beforeend','<p id="otcHelpNote"><b>场外衍生品：</b>回测、参数模板和产品条款共用固定参数注册表，采用自然月、顺延和ACT/365；簿记收益来自人工录入估值或结算数据。</p>');if(commands&&!document.getElementById('otcCommandGroup'))commands.insertAdjacentHTML('beforeend','<section id="otcCommandGroup" class="command-group"><header class="command-head"><h2>场外衍生品</h2><p>一次性只读迁移历史发行产品</p></header><div class="command-row"><code>python app.py otc-ledger-migrate --source &lt;历史发行产品工作簿.xlsx&gt;</code><div class="command-use">只读导入固定第3至15行；相同SHA-256不可重复导入</div></div></section>')}
function otcNumber(v,d){return v==null?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:d==null?2:d})}function otcMoney(v){return v==null?'—':'¥'+otcNumber(v,2)}function otcPercent(v){return v==null?'—':(Number(v)*100).toFixed(2)+'%'}function otcStatus(v){return({queued:'排队中',running:'运行中',completed:'已完成',failed:'失败',interrupted:'已中断'})[v]||v||'—'}function otcSelected(v,e){return v===e?' selected':''}
function otcStructures(){return(otcState.module||{}).structures||[]}function otcIndices(){return((otcState.module||{}).market||{}).indices||[]}function otcInput(def,value,context){const optional=!!def.optional,required=context==='backtest'&&!optional;let actual=value==null?(context==='backtest'?def.default:''):value;if(actual!==''&&actual!=null&&Number(def.step)===.01)actual=Math.round(Number(actual)*100)/100;return`<label class="otc-param" data-structures="${def.structures==='all'?'all':(def.structures||[]).join(',')}">${escapeHtml(def.label)}${optional?'（可空）':''}<input name="${def.name}" type="number" min="${def.min}" max="${def.max}" step="${def.step||1}" value="${actual==null?'':actual}" ${required?'required':''}></label>`}function otcParameterFields(values,context){return((otcState.module||{}).parameter_definitions||[]).map(def=>otcInput(def,(values||{})[def.name],context)).join('')}function otcToggleFields(structure,form){(form||document).querySelectorAll('.otc-param').forEach(x=>{const applies=x.dataset.structures==='all'||x.dataset.structures.split(',').includes(structure);x.hidden=!applies;x.querySelectorAll('input').forEach(i=>i.disabled=!applies)})}function otcReadRequest(form){const data=new FormData(form),payload={};for(const[key,value]of data.entries()){if(value==='')continue;payload[key]=['structure','index_code','start_date','end_date','product_name'].includes(key)?value:Number(value)}return payload}

function renderOtcDerivatives(tab){const host=document.getElementById('dashOtcDerivatives');if(!host)return;otcState.module=RAW.otc_derivatives||otcState.module||{};if(tab==='ledger')renderOtcLedger(host);else if(tab==='pricing')renderOtcPricing(host);else renderOtcBacktest(host);otcEnsurePricingTab(tab)}
function otcEnsurePricingTab(active){const tabs=document.querySelector('#dashOtcDerivatives .otc-tabs');if(!tabs||tabs.querySelector('[data-otc-pricing]'))return;const button=document.createElement('button');button.dataset.otcPricing='1';button.textContent='期权定价';button.className=active==='pricing'?'active':'';button.onclick=()=>dashGo('otc-derivatives',false,'pricing');tabs.appendChild(button)}
function renderOtcBacktest(host){const module=otcState.module,market=module.market||{},indices=market.indices||[],templates=module.templates||[],defaults={};(module.parameter_definitions||[]).forEach(x=>defaults[x.name]=x.default);host.innerHTML=`<div class="otc-head"><div><span class="eyebrow">OTC DERIVATIVES</span><h2>场外衍生品</h2><p>固定指数白名单上的自然月ACT/365历史条款回测。</p></div><span class="dash-pill ${market.status==='current'?'healthy':'attention'}">行情 ${market.status==='current'?'可用':'缺失'} · ${escapeHtml((market.updated_at||'—').replace('T',' '))}</span></div><div class="otc-tabs"><button class="active">期权回测</button><button onclick="dashGo('otc-derivatives',false,'ledger')">产品簿记</button></div><div class="otc-layout"><section class="dash-card otc-form-card"><h3>回测条款</h3><p class="dash-note">自然月观察、非交易日顺延、ACT/365。</p><div class="otc-template-bar"><select id="otcTemplateSelect" onchange="loadOtcTemplate(this.value)"><option value="">载入参数模板</option>${templates.map(x=>`<option value="${x.id}">${escapeHtml(x.name)} · r${x.revision}</option>`).join('')}</select><input id="otcTemplateName" placeholder="模板名称"><button onclick="saveOtcTemplate()">保存模板</button><button class="link-btn negative" onclick="voidOtcTemplate()">作废模板</button></div><form id="otcBacktestForm" onsubmit="submitOtcBacktest(event)"><label>产品名称（可空）<input name="product_name" maxlength="120" placeholder="留空则按结构、指数和截止日自动命名"></label><label>结构<select name="structure" onchange="otcToggleFields(this.value,this.form)">${otcStructures().map(x=>`<option value="${x.code}">${escapeHtml(x.name)}</option>`).join('')}</select></label><label>标的指数<select name="index_code">${indices.map(x=>`<option value="${x.code}" ${x.available?'':'disabled'}>${escapeHtml(x.name)}${x.available?'':'（无缓存）'}</option>`).join('')}</select></label><div class="otc-form-grid"><label>历史起始日<input name="start_date" type="date" value="2012-01-01" required></label><label>评价截止日<input name="end_date" type="date" value="${escapeHtml((indices[0]||{}).last_date||'')}" required></label>${otcParameterFields(defaults,'backtest')}</div><button id="otcRunButton" class="otc-primary" ${market.status==='current'?'':'disabled'}>开始回测</button><div id="otcTaskMessage" class="otc-message"></div></form></section><section class="dash-card otc-history"><div class="card-head"><h3>最近回测</h3><button onclick="refreshOtcModule()">刷新</button></div><div id="otcHistory">${otcHistoryHtml(module.recent_runs||[])}</div></section></div><div id="otcResult"></div>`;const form=document.getElementById('otcBacktestForm');otcToggleFields(form.elements.structure.value,form);if(otcState.activeRun)loadOtcRun(otcState.activeRun)}
function otcHistoryHtml(items){return items.length?items.map(run=>`<button class="otc-run" onclick="loadOtcRun('${run.id}')"><span><b>${escapeHtml((otcStructures().find(x=>x.code===run.request.structure)||{}).name||run.request.structure)}</b><small>${escapeHtml(run.created_at||'')} · ${escapeHtml(run.request.index_code||'')}</small></span><em>${otcStatus(run.status)}</em></button>`).join(''):'<div class="empty-state">尚无回测记录</div>'}
async function refreshOtcModuleData(){const response=await fetch('/api/modules/otc-derivatives');if(response.ok){otcState.module=await response.json();RAW.otc_derivatives=otcState.module}}async function refreshOtcModule(){await refreshOtcModuleData();renderOtcDerivatives('backtest')}
async function loadOtcTemplate(id){if(!id){otcState.template=null;return}const response=await fetch('/api/otc/backtest-templates/'+id),data=await response.json();if(!response.ok)return;otcState.template=data.template;const form=document.getElementById('otcBacktestForm');Object.keys(data.template.request).forEach(k=>{if(form.elements[k])form.elements[k].value=data.template.request[k]==null?'':data.template.request[k]});document.getElementById('otcTemplateName').value=data.template.name;otcToggleFields(data.template.request.structure,form)}
async function saveOtcTemplate(){const form=document.getElementById('otcBacktestForm'),name=document.getElementById('otcTemplateName').value.trim();if(!name){alert('请填写模板名称');return}const existing=otcState.template,url=existing?'/api/otc/backtest-templates/'+existing.id:'/api/otc/backtest-templates',method=existing?'PATCH':'POST',body={name,request:otcReadRequest(form)};if(existing)body.expected_revision=existing.revision;const response=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),data=await response.json();if(!response.ok){alert(data.error||'模板保存失败');return}otcState.template=data.template;await refreshOtcModuleData();renderOtcDerivatives('backtest');await loadOtcTemplate(data.template.id)}
async function voidOtcTemplate(){if(!otcState.template||!confirm('确认作废当前参数模板？'))return;const response=await fetch('/api/otc/backtest-templates/'+otcState.template.id,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({expected_revision:otcState.template.revision})}),data=await response.json();if(!response.ok){alert(data.error||'作废失败');return}otcState.template=null;await refreshOtcModuleData();renderOtcDerivatives('backtest')}
async function submitOtcBacktest(event){event.preventDefault();const button=document.getElementById('otcRunButton'),message=document.getElementById('otcTaskMessage'),payload=otcReadRequest(event.currentTarget);if(otcState.template){payload.template_id=otcState.template.id;payload.template_revision=otcState.template.revision}button.disabled=true;message.textContent='正在计算数据和PDF报告…';try{const response=await fetch('/api/otc/backtests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),body=await response.json();if(!response.ok)throw new Error(body.error||'HTTP '+response.status);otcState.activeRun=body.run.id;pollOtcRun(body.run.id)}catch(error){message.textContent=error.message;button.disabled=false}}
async function fetchOtcRun(id){const response=await fetch('/api/otc/backtests/'+id),data=await response.json();if(!response.ok)throw new Error(data.error||'HTTP '+response.status);if(data.result)otcState.resultSummary=data.result.summary;return data}async function pollOtcRun(id){clearTimeout(otcState.pollTimer);try{const state=await fetchOtcRun(id);if(['queued','running'].includes(state.run.status)){otcState.pollTimer=setTimeout(()=>pollOtcRun(id),1500);return}await refreshOtcModuleData();if(state.run.status==='completed')loadOtcRun(id);else throw new Error(state.run.error||'回测失败')}catch(error){const m=document.getElementById('otcTaskMessage');if(m)m.textContent=error.message}}
async function loadOtcRun(id){otcState.activeRun=id;const host=document.getElementById('otcResult');if(!host)return;host.innerHTML='<div class="dash-card">正在加载…</div>';try{const data=await fetchOtcRun(id),run=data.run;if(run.status!=='completed'){host.innerHTML=`<div class="dash-card">${otcStatus(run.status)}：${escapeHtml(run.error||'任务未完成')}</div>`;return}const r=data.result,s=r.summary,source=r.source;host.innerHTML=`<section class="dash-card otc-result-head"><div><h3>${escapeHtml(r.structure_name)} · ${escapeHtml(r.index_name)}</h3><p>${source.actual_start_date} → ${source.actual_end_date} · 自然月 / ACT365</p></div><div class="otc-downloads">${run.pdf_path?`<a href="/api/otc/backtests/${id}/download.pdf">下载PDF报告</a>`:'<span>旧任务无PDF</span>'}<a href="/api/otc/backtests/${id}/download.xlsx">下载Excel</a><a href="/api/otc/backtests/${id}/download.json">下载JSON</a></div></section><div class="otc-kpis">${[['全部样本',s.total_samples],['已完成',s.completed_samples],['存续中',s.still_running_samples],['正收益概率',otcPercent(s.positive_return_probability)],['平均绝对收益',otcPercent(s.average_absolute_return)],['平均年化收益',otcPercent(s.average_annualized_return)],['平均持有天数',otcNumber(s.average_holding_calendar_days,1)],['敲出且未敲入',s.knocked_out_no_knock_in],['未敲出且未敲入',s.not_knocked_out_no_knock_in],['敲入后敲出',s.knocked_in_then_out],['敲入且未敲出',s.not_knocked_out_knocked_in]].map(x=>`<div><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="otc-chart-grid"><section class="dash-card"><h3>建仓日样本收益</h3><canvas id="otcReturnChart" width="900" height="280"></canvas></section><section class="dash-card"><h3>退出观察月分布</h3><canvas id="otcHoldingChart" width="560" height="280"></canvas></section></div><section class="dash-card"><div class="card-head"><h3>逐样本明细</h3><div id="otcSamplePager"></div></div><div class="otc-table-wrap"><table><thead><tr><th>建仓日</th><th>建仓点位</th><th>退出日</th><th>持有日</th><th>敲入</th><th>敲出</th><th>状态</th><th>绝对收益</th><th>年化收益</th></tr></thead><tbody id="otcSamples"></tbody></table></div></section><p class="dash-note">PDF、Excel、JSON和网页使用同一次本地Wind缓存回测，不访问Oracle或模拟行情。</p>`;drawOtcLine(r.charts.sample_returns||[]);drawOtcBars(r.charts.holding_months||[]);loadOtcSamples(id,1)}catch(error){host.innerHTML=`<div class="dash-card negative">${escapeHtml(error.message)}</div>`}}
async function loadOtcSamples(id,page){const response=await fetch(`/api/otc/backtests/${id}/samples?page=${page}&page_size=50`),data=await response.json();if(!response.ok)return;const body=document.getElementById('otcSamples'),pager=document.getElementById('otcSamplePager');if(!body)return;body.innerHTML=data.items.map(x=>`<tr><td>${x.entry_date}</td><td>${otcNumber(x.entry_price)}</td><td>${x.exit_date||'—'}</td><td>${x.holding_calendar_days==null?'—':x.holding_calendar_days}</td><td>${x.knocked_in?'是':'否'}</td><td>${x.knocked_out?'是':'否'}</td><td>${x.still_running?'存续中':'已完成'}</td><td>${otcPercent(x.absolute_return)}</td><td>${otcPercent(x.annualized_return)}</td></tr>`).join('');const pages=Math.max(1,Math.ceil(data.total/data.page_size));pager.innerHTML=`<button ${page<=1?'disabled':''} onclick="loadOtcSamples('${id}',${page-1})">上一页</button><span>${page}/${pages}</span><button ${page>=pages?'disabled':''} onclick="loadOtcSamples('${id}',${page+1})">下一页</button>`}
function drawOtcLine(points){const c=document.getElementById('otcReturnChart');if(!c||!points.length)return;const x=c.getContext('2d'),w=c.width-64,h=c.height-54,min=Math.min(0,...points.map(p=>p.value)),max=Math.max(0,...points.map(p=>p.value)),span=max-min||1;x.strokeStyle='#167c69';x.beginPath();points.forEach((p,i)=>{const px=48+i/Math.max(points.length-1,1)*w,py=20+(max-p.value)/span*h;i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke()}function drawOtcBars(points){const c=document.getElementById('otcHoldingChart');if(!c||!points.length)return;const x=c.getContext('2d'),max=Math.max(...points.map(p=>p.count),1),slot=(c.width-56)/points.length;points.forEach((p,i)=>{const h=p.count/max*(c.height-54);x.fillStyle='#24578d';x.fillRect(42+i*slot,c.height-34-h,Math.max(2,slot*.65),h)})}

function renderOtcLedger(host){const m=otcState.module||{},ledger=m.ledger||{},f=otcState.ledgerFilters||{};host.innerHTML=`<div class="otc-head"><div><span class="eyebrow">OTC DERIVATIVES</span><h2>场外衍生品</h2><p>发行产品业务字段、系统计算收益、生命周期和附件审计。</p></div><span class="dash-pill healthy">登记 ${ledger.total||0} · 存续 ${ledger.active||0}</span></div><div class="otc-tabs"><button onclick="dashGo('otc-derivatives',false,'backtest')">期权回测</button><button class="active">产品簿记</button></div><section class="dash-card otc-ledger-card"><div class="otc-ledger-actions"><p>默认按起始日从近到远排列；筛选条件默认均为全部。</p><div><button onclick="toggleOtcFilters()" aria-expanded="${otcState.filterOpen}">筛选${Object.values(f).some(Boolean)?' · 已应用':''}</button><button class="otc-primary" onclick="newOtcProduct()">新增发行产品</button></div></div><div id="otcFilterPanel" class="otc-filter-panel" ${otcState.filterOpen?'':'hidden'}><label>产品名称<input id="otcFilterQ" value="${escapeHtml(f.q||'')}" placeholder="名称包含"></label><label>存续或了结<select id="otcFilterLifecycle"><option value="">全部</option><option${otcSelected(f.lifecycle,'存续')}>存续</option><option${otcSelected(f.lifecycle,'了结')}>了结</option><option${otcSelected(f.lifecycle,'其他')}>其他</option></select></label><label>正式状态<select id="otcFilterStatus"><option value="">全部</option>${(m.statuses||[]).map(x=>`<option${otcSelected(f.status,x)}>${escapeHtml(x)}</option>`).join('')}</select></label><label>原策略<select id="otcFilterStrategy"><option value="">全部</option>${(m.strategy_names||[]).map(x=>`<option${otcSelected(f.strategy_name,x)}>${escapeHtml(x)}</option>`).join('')}</select></label><label>标准结构<select id="otcFilterStructure"><option value="">全部</option>${otcStructures().map(x=>`<option value="${x.code}"${otcSelected(f.structure,x.code)}>${escapeHtml(x.name)}</option>`).join('')}</select></label><label>标的<select id="otcFilterIndex"><option value="">全部</option>${otcIndices().map(x=>`<option value="${x.code}"${otcSelected(f.index_code,x.code)}>${escapeHtml(x.name)}</option>`).join('')}</select></label><label>起始日从<input id="otcFilterStartFrom" type="date" value="${f.start_from||''}"></label><label>起始日至<input id="otcFilterStartTo" type="date" value="${f.start_to||''}"></label><label>终止日从<input id="otcFilterEndFrom" type="date" value="${f.end_from||''}"></label><label>终止日至<input id="otcFilterEndTo" type="date" value="${f.end_to||''}"></label><div class="otc-filter-actions"><button class="otc-primary" onclick="applyOtcFilters()">应用筛选</button><button onclick="resetOtcFilters()">重置</button></div></div><div class="otc-wide-table"><table><thead><tr><th class="otc-name-col">${otcSortHead('产品名称','name')}</th><th>${otcSortHead('起始日','start_date')}</th><th>${otcSortHead('终止日','end_date')}</th><th>存续或了结</th><th>原策略 / 标准结构</th><th>标的</th><th>${otcSortHead('规模 / 期限','notional')}</th><th>估值或结算 / 派息</th><th>报酬基准 / 比例</th><th>${otcSortHead('费前绝对 / 年化','gross_absolute_return')}</th><th>业绩报酬</th><th>${otcSortHead('费后绝对 / 年化','net_absolute_return')}</th><th>备注</th></tr></thead><tbody id="otcProductRows"><tr><td colspan="13">正在加载…</td></tr></tbody></table></div><div id="otcProductPager" class="otc-pager"></div></section><p class="dash-note">了结产品按终止日和最终结算数据自动计算收益；存续产品为当前估值参考口径。表尾合计覆盖完整筛选结果，仅统计产品数量和名义本金规模。</p><div id="otcDrawerShade" class="otc-drawer-shade" onclick="closeOtcProductDrawer()"></div><aside id="otcProductDrawer" class="otc-product-drawer"><button class="otc-drawer-close" onclick="closeOtcProductDrawer()" aria-label="关闭">×</button><div id="otcProductEditor"><div class="empty-state">选择产品查看或修改。</div></div></aside>`;loadOtcProducts(1)}
function otcQueryValue(id){return(document.getElementById(id)||{}).value||''}function otcSortHead(label,key){const mark=otcState.ledgerSort===key?(otcState.ledgerSortDir==='asc'?' ↑':' ↓'):'';return`<button class="otc-sort" data-sort="${key}" data-label="${label}" onclick="sortOtcProducts('${key}')">${label}${mark}</button>`}function sortOtcProducts(key){if(otcState.ledgerSort===key)otcState.ledgerSortDir=otcState.ledgerSortDir==='asc'?'desc':'asc';else{otcState.ledgerSort=key;otcState.ledgerSortDir=key==='name'?'asc':'desc'}document.querySelectorAll('.otc-sort').forEach(x=>x.textContent=x.dataset.label+(x.dataset.sort===otcState.ledgerSort?(otcState.ledgerSortDir==='asc'?' ↑':' ↓'):''));loadOtcProducts(1)}
function toggleOtcFilters(){otcState.filterOpen=!otcState.filterOpen;const p=document.getElementById('otcFilterPanel');if(p)p.hidden=!otcState.filterOpen;const b=document.querySelector('.otc-ledger-actions button[aria-expanded]');if(b)b.setAttribute('aria-expanded',String(otcState.filterOpen))}
function applyOtcFilters(){otcState.ledgerFilters={q:otcQueryValue('otcFilterQ').trim(),lifecycle:otcQueryValue('otcFilterLifecycle'),status:otcQueryValue('otcFilterStatus'),strategy_name:otcQueryValue('otcFilterStrategy'),structure:otcQueryValue('otcFilterStructure'),index_code:otcQueryValue('otcFilterIndex'),start_from:otcQueryValue('otcFilterStartFrom'),start_to:otcQueryValue('otcFilterStartTo'),end_from:otcQueryValue('otcFilterEndFrom'),end_to:otcQueryValue('otcFilterEndTo')};loadOtcProducts(1)}
function resetOtcFilters(){otcState.ledgerFilters={};renderOtcLedger(document.getElementById('dashOtcDerivatives'))}
function otcLedgerQuery(page){const values={page:String(page||1),page_size:'50',sort_by:otcState.ledgerSort,sort_dir:otcState.ledgerSortDir};Object.entries(otcState.ledgerFilters||{}).forEach(([k,v])=>{if(v)values[k]=v});return new URLSearchParams(values)}
async function loadOtcProducts(page){const query=otcLedgerQuery(page),response=await fetch('/api/otc/products?'+query),data=await response.json(),host=document.getElementById('otcProductRows');if(!host)return;if(!response.ok){host.innerHTML=`<tr><td colspan="13">${escapeHtml(data.error||'加载失败')}</td></tr>`;return}host.innerHTML=data.items.length?data.items.map(otcProductTableRow).join('')+otcProductTotalRow(data.aggregates||{}):'<tr><td colspan="13"><div class="empty-state">没有发行产品</div></td></tr>';const pages=Math.max(1,Math.ceil(data.total/data.page_size));document.getElementById('otcProductPager').innerHTML=`<span>筛选命中 ${data.total} 项</span><button ${page<=1?'disabled':''} onclick="loadOtcProducts(${page-1})">上一页</button><span>${page}/${pages}</span><button ${page>=pages?'disabled':''} onclick="loadOtcProducts(${page+1})">下一页</button>`}
function otcProductTableRow(x){const r=x.returns||{},structure=(otcStructures().find(s=>s.code===x.structure)||{}).name||'待结构化',term=(x.terms||{}).term_months,basis=r.basis==='settlement'?'最终结算':'当前估值';return`<tr class="otc-ledger-row" onclick="openOtcProduct('${x.id}')"><td class="otc-name-col"><b>${escapeHtml(x.name)}</b></td><td>${x.start_date||'—'}</td><td>${x.end_date||'—'}</td><td><span>${escapeHtml(x.lifecycle_group||'其他')}</span><small>${escapeHtml(x.status||'—')}</small></td><td><span>${escapeHtml(x.strategy_name||'—')}</span><small>${escapeHtml(structure)}</small></td><td>${escapeHtml(x.index_code||'—')}</td><td><span>${otcMoney(x.notional)}</span><small>${term==null?'期限待补':term+'个月'}</small></td><td><span>${otcMoney(x.valuation_amount)}</span><small>${basis} · 派息 ${otcMoney(x.cumulative_distributions)}</small></td><td><span>${otcPercent(x.performance_hurdle)}</span><small>提取 ${otcPercent(x.performance_fee_rate)}</small></td><td><span>${otcPercent(r.gross_absolute_return)}</span><small>年化 ${otcPercent(r.gross_annualized_return)}</small></td><td>${otcMoney(r.performance_fee)}</td><td><span>${otcPercent(r.net_absolute_return)}</span><small>年化 ${otcPercent(r.net_annualized_return)}</small></td><td class="otc-notes-cell">${escapeHtml(x.notes||'—')}</td></tr>`}
function otcProductTotalRow(a){const sums=a.sums||{};return`<tr class="otc-ledger-total"><td class="otc-name-col"><b>合计</b><small>产品数量 ${a.count||0}</small></td><td colspan="5"></td><td><b>${otcMoney(sums.notional)}</b></td><td colspan="6"></td></tr>`}
function openOtcProductDrawer(){document.getElementById('otcProductDrawer').classList.add('open');document.getElementById('otcDrawerShade').classList.add('open')}function closeOtcProductDrawer(){document.getElementById('otcProductDrawer').classList.remove('open');document.getElementById('otcDrawerShade').classList.remove('open')}
function newOtcProduct(){otcState.product=null;otcState.productTemplate=null;renderOtcProductEditor({terms:{},reference:{},status:'草稿',events:[],audit:[],returns:{}});openOtcProductDrawer()}async function openOtcProduct(id){const response=await fetch('/api/otc/products/'+id),data=await response.json();if(response.ok){otcState.product=data.product;otcState.productTemplate=null;renderOtcProductEditor(data.product);openOtcProductDrawer()}}
function renderOtcProductEditor(p){const host=document.getElementById('otcProductEditor');if(!host)return;const t=p.terms||{},templates=(otcState.module||{}).templates||[],r=p.returns||{},settled=p.lifecycle_group==='了结';host.innerHTML=`<div class="card-head"><div><h3>${p.id?'产品条款、收益与生命周期':'新增发行产品'}</h3><p>${p.id?'状态 '+escapeHtml(p.status):'同名产品允许独立保存'}</p></div>${p.id?'<button class="link-btn negative" onclick="voidOtcProduct()">作废</button>':''}</div><form id="otcProductForm" onsubmit="saveOtcProduct(event)"><div class="otc-form-grid"><label>产品名称<input name="name" value="${escapeHtml(p.name||'')}" required></label><label>原始策略名称<input name="strategy_name" value="${escapeHtml(p.strategy_name||'')}"></label><label>载入参数模板<select name="template_picker" onchange="applyTemplateToProduct(this.value)"><option value="">不载入</option>${templates.map(x=>`<option value="${x.id}">${escapeHtml(x.name)} · r${x.revision}</option>`).join('')}</select></label><label>回测结构<select name="structure" onchange="otcToggleFields(this.value,this.form)"><option value="">未结构化</option>${otcStructures().map(x=>`<option value="${x.code}"${otcSelected(p.structure,x.code)}>${escapeHtml(x.name)}</option>`).join('')}</select></label><label>标的<select name="index_code"><option value="">未填写</option>${otcIndices().map(x=>`<option value="${x.code}"${otcSelected(p.index_code,x.code)}>${escapeHtml(x.name)}</option>`).join('')}</select></label><label>名义本金（元）<input name="notional" type="number" min="0" step="0.01" value="${p.notional==null?'':p.notional}"></label><label>起息日<input name="start_date" type="date" value="${p.start_date||''}"></label><label>正式结束日<input name="end_date" type="date" value="${p.end_date||''}"></label>${otcParameterFields(t,'product')}<label>年化业绩报酬提取基准<input name="performance_hurdle" type="number" min="0" max="1" step="0.0001" value="${p.performance_hurdle==null?'':p.performance_hurdle}"></label><label>超额业绩报酬提取比例<input name="performance_fee_rate" type="number" min="0" max="1" step="0.0001" value="${p.performance_fee_rate==null?'':p.performance_fee_rate}"></label><label>收益截止日${settled?'<small>已了结产品固定使用终止日</small>':''}<input name="return_as_of_date" type="date" value="${p.return_as_of_date||''}" ${settled?'disabled':''}></label><label>${settled?'最终结算金额':'当前估值金额'}<input name="valuation_amount" type="number" min="0" step="0.01" value="${p.valuation_amount==null?'':p.valuation_amount}"></label><label>累计已派息金额<input name="cumulative_distributions" type="number" min="0" step="0.01" value="${p.cumulative_distributions==null?'':p.cumulative_distributions}"></label></div>${p.legacy_annual_return==null?'':`<p class="dash-note">原表年化收益率（导入追溯，只读）：${otcPercent(p.legacy_annual_return)}</p>`}<section class="otc-return-box"><b>产品收益（ACT/365 · ${settled?'最终结算':'当前估值'}口径）</b><span>费前绝对 ${otcPercent(r.gross_absolute_return)} · 年化 ${otcPercent(r.gross_annualized_return)}</span><span>业绩报酬 ${otcMoney(r.performance_fee)} · 费后绝对 ${otcPercent(r.net_absolute_return)} · 年化 ${otcPercent(r.net_annualized_return)}</span>${r.fee_terms_missing?'<em>业绩报酬条款待补，仅计算费前收益</em>':''}${(r.missing||[]).length?`<em>缺少：${escapeHtml(r.missing.join('、'))}</em>`:''}</section><label>备注<textarea name="notes">${escapeHtml(p.notes||'')}</textarea></label><div class="otc-editor-actions"><button class="otc-primary">保存修订</button>${p.id&&p.structure?'<button type="button" onclick="backtestOtcProduct()">按当前条款回测</button>':''}${p.id?'<button id="otcFieldAuditButton" type="button" onclick="runOtcFieldAudit()" disabled>字段排查（API待启用）</button>':''}<span id="otcProductMessage"></span></div></form>${p.id?otcAttachmentEditor()+otcEventEditor(p):''}`;const form=document.getElementById('otcProductForm');otcToggleFields(p.structure||'',form);if(p.id){otcState.fieldAudit=p.latest_field_audit||null;loadOtcAttachments(p.id);renderOtcFieldAudit(otcState.fieldAudit);loadOtcLlmStatus()}}
async function applyTemplateToProduct(id){if(!id)return;const response=await fetch('/api/otc/backtest-templates/'+id),data=await response.json();if(!response.ok)return;const form=document.getElementById('otcProductForm'),t=data.template;otcState.productTemplate=t;Object.keys(t.request).forEach(k=>{if(form.elements[k]&&!['start_date','end_date'].includes(k))form.elements[k].value=t.request[k]==null?'':t.request[k]});otcToggleFields(t.request.structure,form)}
function otcAttachmentEditor(){const categories=(otcState.module||{}).attachment_categories||['产品合同','投资者名单','公告','回测报告','宣传材料','其他'];return`<hr><section class="otc-attachments"><div class="card-head"><div><h3>产品附件</h3><p>附件独立归属于本产品，不进入全局知识库。</p></div></div><div class="otc-attachment-upload"><select id="otcAttachmentCategory">${categories.map(x=>`<option>${escapeHtml(x)}</option>`).join('')}</select><input id="otcAttachmentFile" type="file" accept=".pdf,.docx,.xls,.xlsx,.pptx,.txt,.md,.markdown,.html,.htm"><button type="button" onclick="uploadOtcAttachment()">上传附件</button></div><div id="otcAttachmentMessage" class="otc-message"></div><div id="otcAttachmentList"><div class="empty-state">正在加载附件…</div></div><div id="otcAttachmentPreview"></div><div id="otcFieldAuditResult"></div></section>`}
function otcFileBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(new Error('文件读取失败'));reader.readAsDataURL(file)})}
async function otcJsonResponse(response){const raw=await response.text();try{return JSON.parse(raw)}catch(error){if(raw.trim().startsWith('<'))throw new Error('当前后台未加载附件接口，请重启网页服务后刷新页面');throw new Error('服务器返回了无法识别的响应（HTTP '+response.status+'）')}}
async function loadOtcAttachments(productId){const host=document.getElementById('otcAttachmentList');if(!host)return;try{const response=await fetch(`/api/otc/products/${productId}/attachments`),data=await otcJsonResponse(response);if(!response.ok)throw new Error(data.error||'附件加载失败');host.innerHTML=data.attachments.length?data.attachments.map(x=>`<div class="otc-attachment-row"><span><b>${escapeHtml(x.original_name)}</b><small>${escapeHtml(x.category)} · ${otcNumber(x.size,0)} B · ${x.extraction_status==='needs_ocr'?'需OCR':x.extraction_status==='ok'?'文本已提取':'提取失败'}</small></span><div><button type="button" onclick="previewOtcAttachment('${x.id}')">预览文本</button><a href="/api/otc/products/${productId}/attachments/${x.id}/download">下载</a><button type="button" class="link-btn negative" onclick="deleteOtcAttachment('${x.id}',${x.revision})">停用</button></div></div>`).join(''):'<div class="empty-state">尚无附件</div>'}catch(error){host.innerHTML=`<div class="negative">${escapeHtml(error.message)}</div>`}}
async function uploadOtcAttachment(){const input=document.getElementById('otcAttachmentFile'),message=document.getElementById('otcAttachmentMessage'),file=input.files[0];if(!file){message.textContent='请选择附件';return}message.textContent='正在上传并提取文本…';try{const content=await otcFileBase64(file),response=await fetch(`/api/otc/products/${otcState.product.id}/attachments`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:file.name,content_base64:content,category:otcQueryValue('otcAttachmentCategory')})}),data=await otcJsonResponse(response);if(!response.ok)throw new Error(data.error||'上传失败');message.textContent=data.duplicate?'相同附件已关联，无需重复保存':'附件已保存';input.value='';loadOtcAttachments(otcState.product.id)}catch(error){message.textContent=error.message}}
async function previewOtcAttachment(id){const host=document.getElementById('otcAttachmentPreview');try{const response=await fetch(`/api/otc/products/${otcState.product.id}/attachments/${id}`),data=await otcJsonResponse(response);if(!response.ok)throw new Error(data.error||'预览失败');const x=data.attachment;host.innerHTML=`<details open><summary>${escapeHtml(x.original_name)} · 文本预览</summary>${x.extraction_status==='needs_ocr'?'<p>扫描件无文本层，需OCR；原文件已保留。</p>':`<pre>${escapeHtml(x.text_content||'未提取到文本')}</pre>`}</details>`}catch(error){host.innerHTML=`<div class="negative">${escapeHtml(error.message)}</div>`}}
async function deleteOtcAttachment(id,revision){if(!confirm('确认停用此附件关联？原始内容不会物理删除。'))return;const response=await fetch(`/api/otc/products/${otcState.product.id}/attachments/${id}`,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({expected_revision:revision})}),data=await response.json();if(!response.ok){alert(data.error||'附件停用失败');return}loadOtcAttachments(otcState.product.id)}
function renderOtcFieldAudit(task){const host=document.getElementById('otcFieldAuditResult');if(!host)return;if(!task||task.status!=='completed'){host.innerHTML='';return}const result=(task.result||{}).result||task.result||{},rows=result.fields||[],source=task.provider==='assistant_manual'?'助手离线排查':'模型排查';host.innerHTML=`<section class="otc-audit-result"><h3>最近字段排查提示</h3><p>${escapeHtml(source)} · ${escapeHtml(task.finished_at||task.created_at||'')}。结果只作人工复核提示，不会修改产品数据；投资者名单未参与排查。</p>${rows.map(x=>`<div><b>${escapeHtml(x.field)}</b><span>${escapeHtml(x.status)} · 人工值 ${escapeHtml(String(x.input_value==null?'—':x.input_value))} · 文件值 ${escapeHtml(String(x.document_value==null?'—':x.document_value))}</span>${(x.evidence||[]).map(e=>`<small>证据 ${escapeHtml(e.location||'位置未标明')}：${escapeHtml(e.quote||'—')}</small>`).join('')}</div>`).join('')||'<div>没有可展示的核对字段</div>'}</section>`}
async function loadOtcLlmStatus(){const button=document.getElementById('otcFieldAuditButton');if(!button)return;try{const response=await fetch('/api/llm/status'),data=await response.json(),hasResult=!!(otcState.fieldAudit&&otcState.fieldAudit.status==='completed');otcState.llmStatus=data;button.disabled=!response.ok||(!data.enabled&&!hasResult);if(data.enabled)button.textContent='重新字段排查';else if(hasResult)button.textContent='查看字段排查结果（API待启用）';else button.textContent='字段排查（API待启用）';button.title=data.message||''}catch(error){const hasResult=!!otcState.fieldAudit;button.disabled=!hasResult;button.textContent=hasResult?'查看字段排查结果（API待启用）':'字段排查（API待启用）'}}
async function runOtcFieldAudit(){const button=document.getElementById('otcFieldAuditButton'),host=document.getElementById('otcFieldAuditResult');if(!(otcState.llmStatus||{}).enabled&&otcState.fieldAudit){renderOtcFieldAudit(otcState.fieldAudit);host.scrollIntoView({behavior:'smooth',block:'nearest'});return}button.disabled=true;host.innerHTML='<p>正在核对人工字段与非投资者名单附件…</p>';const response=await fetch('/api/llm/tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_type:'otc_field_audit',product_id:otcState.product.id,expected_revision:otcState.product.revision})}),data=await response.json();if(!response.ok){host.innerHTML=`<p class="negative">${escapeHtml(data.error||'字段排查无法启动')}</p>`;button.disabled=!(otcState.llmStatus||{}).enabled;return}pollOtcFieldAudit(data.task_id)}
async function pollOtcFieldAudit(id){const host=document.getElementById('otcFieldAuditResult'),button=document.getElementById('otcFieldAuditButton'),response=await fetch('/api/llm/tasks/'+id),task=await response.json();if(!response.ok){host.innerHTML=`<p class="negative">${escapeHtml(task.error||'字段排查失败')}</p>`;button.disabled=false;return}if(task.status==='running'){setTimeout(()=>pollOtcFieldAudit(id),1500);return}button.disabled=false;if(task.status!=='completed'){host.innerHTML=`<p class="negative">${escapeHtml(task.error||'字段排查失败')}</p>`;return}otcState.fieldAudit=task;renderOtcFieldAudit(task)}
function otcEventEditor(p){return`<hr><h3>确认生命周期事件</h3><form id="otcEventForm" class="otc-event-form" onsubmit="addOtcEvent(event)"><select name="event_type">${(otcState.module.event_types||[]).map(x=>`<option>${escapeHtml(x)}</option>`).join('')}</select><input type="date" name="event_date" required><input name="note" placeholder="确认依据"><button>确认事件</button></form><div class="otc-timeline">${(p.events||[]).map(x=>`<div><b>${x.event_date} · ${escapeHtml(x.event_type)}</b><span>${escapeHtml((x.values||{}).note||'—')}</span></div>`).join('')||'尚无事件'}</div><details><summary>审计记录</summary>${(p.audit||[]).map(x=>`<p>${escapeHtml(x.created_at)} · ${escapeHtml(x.actor)} · ${escapeHtml(x.action)}</p>`).join('')}</details>`}
async function saveOtcProduct(event){event.preventDefault();const form=event.currentTarget,data=new FormData(form),terms={};((otcState.module||{}).parameter_definitions||[]).forEach(def=>{const input=form.elements[def.name];if(input&&!input.disabled&&input.value!=='')terms[def.name]=Number(input.value)});const nullable=k=>data.get(k)===''?null:data.get(k),values={name:data.get('name'),strategy_name:data.get('strategy_name'),structure:data.get('structure'),index_code:data.get('index_code'),notional:nullable('notional'),start_date:nullable('start_date'),end_date:nullable('end_date'),performance_hurdle:nullable('performance_hurdle'),performance_fee_rate:nullable('performance_fee_rate'),return_as_of_date:(otcState.product||{}).lifecycle_group==='了结'?(otcState.product||{}).return_as_of_date:nullable('return_as_of_date'),valuation_amount:nullable('valuation_amount'),cumulative_distributions:nullable('cumulative_distributions'),terms,template_id:otcState.productTemplate?otcState.productTemplate.id:(otcState.product||{}).template_id||null,template_revision:otcState.productTemplate?otcState.productTemplate.revision:(otcState.product||{}).template_revision||null,reference:(otcState.product||{}).reference||{},notes:data.get('notes')},existing=otcState.product,url=existing?'/api/otc/products/'+existing.id:'/api/otc/products',method=existing?'PATCH':'POST',body=existing?{values,expected_revision:existing.revision}:{values};const response=await fetch(url,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),result=await response.json();if(!response.ok){document.getElementById('otcProductMessage').textContent=result.error||'保存失败';return}otcState.product=result.product;otcState.productTemplate=null;renderOtcProductEditor(result.product);loadOtcProducts(1);refreshOtcModuleData()}
async function addOtcEvent(event){event.preventDefault();const data=new FormData(event.currentTarget),response=await fetch('/api/otc/products/'+otcState.product.id+'/events',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event_type:data.get('event_type'),event_date:data.get('event_date'),values:{note:data.get('note')},expected_revision:otcState.product.revision})}),body=await response.json();if(response.ok){otcState.product=body.product;renderOtcProductEditor(body.product);loadOtcProducts(1)}else alert(body.error||'事件保存失败')}async function voidOtcProduct(){if(!otcState.product||!confirm('确认作废？'))return;const response=await fetch('/api/otc/products/'+otcState.product.id,{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({expected_revision:otcState.product.revision})}),body=await response.json();if(response.ok){otcState.product=body.product;renderOtcProductEditor(body.product);loadOtcProducts(1)}else alert(body.error||'作废失败')}async function backtestOtcProduct(){const index=otcIndices().find(x=>x.code===otcState.product.index_code)||{},response=await fetch('/api/otc/backtests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product_id:otcState.product.id,product_revision:otcState.product.revision,start_date:index.first_date,end_date:index.last_date})}),body=await response.json();if(!response.ok){alert(body.error||'提交失败');return}otcState.activeRun=body.run.id;dashGo('otc-derivatives',false,'backtest')}

function renderOtcPricing(host){host.innerHTML='<div class="dash-card">正在加载期权定价研究…</div>';loadOtcPricingPage(host)}
async function loadOtcPricingPage(host){try{const response=await fetch('/api/otc/pricing'),data=await response.json();if(!response.ok)throw new Error(data.error||'HTTP '+response.status);otcState.pricing=data;const defs=data.parameter_definitions||[],defaults={};defs.forEach(x=>defaults[x.name]=x.default);host.innerHTML=`<div class="otc-head"><div><span class="eyebrow">OTC PRICING RESEARCH</span><h2>场外衍生品</h2><p>经典雪球新发行条款的参数化理论定价研究。</p></div><span class="dash-pill healthy">常数波动率 GBM · 8 × 4096路径</span></div><div class="otc-tabs"><button onclick="dashGo('otc-derivatives',false,'backtest')">期权回测</button><button onclick="dashGo('otc-derivatives',false,'ledger')">产品簿记</button><button class="active" data-otc-pricing>期权定价</button></div><div class="otc-pricing-layout"><section class="dash-card otc-form-card"><h3>条款与模型参数</h3><p class="dash-note">S0=1；每月m/12观察；敲入按1/365监控；全部本金及收益现金流按实际终止时点贴现。</p><label>从产品簿记复制（可选）<select id="otcPricingProduct" onchange="copyOtcPricingProduct(this.value)"><option value="">独立试算</option>${(data.products||[]).map(x=>`<option value="${x.id}">${escapeHtml(x.name)} · r${x.revision}</option>`).join('')}</select></label><div class="otc-structure-cards">${(data.structures||[]).map(x=>`<button type="button" class="${x.enabled?'active':'disabled'}" ${x.enabled?'':'disabled'}>${escapeHtml(x.name)}${x.enabled?'':' · 研发中'}</button>`).join('')}</div><form id="otcPricingForm" onsubmit="submitOtcPricing(event)"><input type="hidden" name="structure" value="classic_snowball"><input type="hidden" name="product_id"><input type="hidden" name="product_revision"><label>研究名称（可空）<input name="product_name" maxlength="120" placeholder="经典雪球理论定价"></label><label>标的指数<select name="index_code">${(data.indices||[]).map(x=>`<option value="${x.code}">${escapeHtml(x.name)}</option>`).join('')}</select></label><div class="otc-form-grid">${defs.map(def=>otcPricingInput(def,defaults[def.name])).join('')}</div><button id="otcPricingButton" class="otc-primary">开始理论定价</button><div id="otcPricingMessage" class="otc-message"></div></form></section><aside><section class="dash-card"><h3>历史参考值</h3><p class="dash-note">参考值不会自动进入模型，点击后仅填入输入框。</p><div id="otcPricingReferences">${otcPricingReferencesHtml(data.references)}</div></section><section class="dash-card otc-pricing-model"><h3>模型边界</h3><p>常数波动率风险中性GBM，贴水率正数表示远期低于现货。历史波动率、股指期货贴水和国债收益率只作人工假设参考。</p><p><b>不是</b>期权链校准后的市场价格、交易报价、会计公允价值或结算价。</p></section><section class="dash-card"><div class="card-head"><h3>近期任务</h3><button onclick="loadOtcPricingPage(document.getElementById('dashOtcDerivatives'))">刷新</button></div><div id="otcPricingHistory">${otcPricingHistoryHtml(data.recent_runs||[])}</div></section></aside></div><div id="otcPricingResult"></div>`;if(otcState.pricingRun)loadOtcPricingRun(otcState.pricingRun)}catch(error){host.innerHTML=`<div class="dash-card negative">${escapeHtml(error.message)}</div>`}}
function otcPricingInput(def,value){const optional=def.default==null,maximum=def.max_from?'':(def.max==null?'':`max="${def.max}"`),minimum=def.min_exclusive!=null?`min="0.000001"`:(def.min==null?'':`min="${def.min}"`);return`<label>${escapeHtml(def.label)}<input name="${def.name}" type="number" ${minimum} ${maximum} step="${def.step||'any'}" value="${value==null?'':value}" ${optional?'':'required'}></label>`}
function otcPricingReferencesHtml(refs){const rows=(refs&&refs.indices)||[];return rows.map(index=>`<article class="otc-reference"><b>${escapeHtml(index.name)} <small>${escapeHtml(index.as_of||'无数据')}</small></b><div>${Object.entries(index.volatility||{}).map(([window,value])=>`<button ${value==null?'disabled':''} onclick="useOtcPricingReference('volatility',${value==null?'null':value})">${window}日波动 ${value==null?'—':otcPercent(value)}</button>`).join('')}</div><div>${(index.basis||[]).map(x=>`<button ${x.latest==null?'disabled':''} onclick="useOtcPricingReference('basis_rate',${x.latest==null?'null':x.latest})">${escapeHtml(x.tenor)} ${x.latest==null?'—':otcPercent(x.latest)}</button>`).join('')}</div></article>`).join('')+((refs||{}).discount_rate&&refs.discount_rate.available?`<article class="otc-reference"><b>中国10年期国债 <small>${escapeHtml(refs.discount_rate.as_of||'')}</small></b><button onclick="useOtcPricingReference('discount_rate',${refs.discount_rate.value})">填入 ${otcPercent(refs.discount_rate.value)}</button></article>`:'<p>贴现率参考不可用</p>')}
function useOtcPricingReference(field,value){const form=document.getElementById('otcPricingForm');if(form&&form.elements[field]&&value!=null){form.elements[field].value=Number(value).toFixed(6);form.elements[field].focus()}}
function copyOtcPricingProduct(id){const p=(otcState.pricing.products||[]).find(x=>x.id===id),form=document.getElementById('otcPricingForm');if(!form)return;form.elements.product_id.value=p?p.id:'';form.elements.product_revision.value=p?p.revision:'';if(!p)return;form.elements.product_name.value=p.name||'';form.elements.index_code.value=p.index_code||'000852';form.elements.notional.value=p.notional==null?'':p.notional;Object.entries(p.terms||{}).forEach(([key,value])=>{if(form.elements[key]&&value!=null)form.elements[key].value=value})}
function otcReadPricing(form){const data=new FormData(form),payload={};for(const[key,value]of data.entries()){if(value==='')continue;payload[key]=['structure','index_code','product_name','product_id'].includes(key)?value:Number(value)}return payload}
async function submitOtcPricing(event){event.preventDefault();const button=document.getElementById('otcPricingButton'),message=document.getElementById('otcPricingMessage'),payload=otcReadPricing(event.currentTarget);button.disabled=true;message.textContent='正在运行8个独立扰动批次…';try{const response=await fetch('/api/otc/pricing/runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),body=await response.json();if(!response.ok)throw new Error(body.error||'HTTP '+response.status);otcState.pricingRun=body.run.id;pollOtcPricing(body.run.id)}catch(error){message.textContent=error.message;message.classList.add('error');button.disabled=false}}
async function pollOtcPricing(id){clearTimeout(otcState.pricingPollTimer);try{const response=await fetch('/api/otc/pricing/runs/'+id),data=await response.json();if(!response.ok)throw new Error(data.error||'HTTP '+response.status);if(['queued','running'].includes(data.run.status)){otcState.pricingPollTimer=setTimeout(()=>pollOtcPricing(id),1200);return}if(data.run.status!=='completed')throw new Error(data.run.error||'定价任务失败');loadOtcPricingRun(id)}catch(error){const m=document.getElementById('otcPricingMessage');if(m)m.textContent=error.message;const b=document.getElementById('otcPricingButton');if(b)b.disabled=false}}
function otcPricingHistoryHtml(items){return items.length?items.map(run=>`<button class="otc-run" onclick="loadOtcPricingRun('${run.id}')"><span><b>${escapeHtml(run.request.product_name||'经典雪球理论定价')}</b><small>${escapeHtml(run.created_at||'')} · ${escapeHtml(run.request.index_code||'')}</small></span><em>${otcStatus(run.status)}</em></button>`).join(''):'<div class="empty-state">尚无定价研究记录</div>'}
async function loadOtcPricingRun(id){otcState.pricingRun=id;const host=document.getElementById('otcPricingResult');if(!host)return;host.innerHTML='<section class="dash-card">正在加载定价结果…</section>';try{const response=await fetch('/api/otc/pricing/runs/'+id),data=await response.json();if(!response.ok)throw new Error(data.error||'HTTP '+response.status);if(data.run.status!=='completed'){host.innerHTML=`<section class="dash-card">${otcStatus(data.run.status)} · ${escapeHtml(data.run.error||'任务未完成')}</section>`;return}const r=data.result,f=r.fair_coupon||{},p=r.probabilities||{};host.innerHTML=`<section class="dash-card otc-result-head"><div><h3>${escapeHtml((r.request||{}).product_name||'经典雪球理论定价')}</h3><p>${escapeHtml(r.model_name)} · ${r.path_count}条路径</p></div><div class="otc-downloads"><a href="/api/otc/pricing/runs/${id}/download.json">下载JSON</a></div></section><div class="otc-kpis">${[['每100本金理论价值',otcNumber(r.value_per_100,4)],['理论估值金额',otcMoney(r.valuation_amount)],['相对平价差',otcNumber(r.par_spread_per_100,4)],['公平前段票息',otcPercent(f.first_coupon)],['公平后段票息',otcPercent(f.second_coupon)],['标准误（每100）',otcNumber(r.standard_error_per_100,5)],['95%置信区间',(r.confidence_interval_95_per_100||[]).map(x=>otcNumber(x,4)).join(' ～ ')],['敲入概率',otcPercent(p.knock_in)],['敲出概率',otcPercent(p.knock_out)],['到期亏损概率',otcPercent(p.maturity_loss)],['平均存续期',otcNumber(r.average_life_years,3)+' 年'],['发行人负债价值',otcNumber(r.issuer_liability_per_100,4)]].map(x=>`<div><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="otc-chart-grid"><section class="dash-card"><h3>终止月份分布</h3><canvas id="otcPricingTermination" width="700" height="280"></canvas></section><section class="dash-card"><h3>收益分布（贴现后每100）</h3><canvas id="otcPricingReturns" width="700" height="280"></canvas></section><section class="dash-card"><h3>批次收敛</h3><canvas id="otcPricingConvergence" width="700" height="280"></canvas></section></div><p class="warn">${escapeHtml(r.disclaimer)}</p>`;drawOtcPricingBars(r.termination_distribution||[]);drawOtcPricingHistogram(r.return_distribution||[]);drawOtcPricingConvergence(r.batch_convergence||[])}catch(error){host.innerHTML=`<section class="dash-card negative">${escapeHtml(error.message)}</section>`}}
function drawOtcPricingBars(points){const c=document.getElementById('otcPricingTermination');if(!c||!points.length)return;const x=c.getContext('2d'),max=Math.max(...points.map(p=>p.probability),.01),slot=(c.width-60)/points.length;x.clearRect(0,0,c.width,c.height);points.forEach((p,i)=>{const h=p.probability/max*(c.height-60);x.fillStyle='#167c69';x.fillRect(45+i*slot,c.height-35-h,Math.max(3,slot*.65),h);x.fillStyle='#52657a';x.font='11px sans-serif';x.fillText(String(p.month),45+i*slot,c.height-16)})}
function drawOtcPricingHistogram(points){const c=document.getElementById('otcPricingReturns');if(!c||!points.length)return;const x=c.getContext('2d'),max=Math.max(...points.map(p=>p.count),1),slot=(c.width-60)/points.length;x.clearRect(0,0,c.width,c.height);points.forEach((p,i)=>{const h=p.count/max*(c.height-55);x.fillStyle=p.upper<0?'#0a8b72':'#d95d4f';x.fillRect(42+i*slot,c.height-30-h,Math.max(2,slot*.8),h)})}
function drawOtcPricingConvergence(points){const c=document.getElementById('otcPricingConvergence');if(!c||!points.length)return;const x=c.getContext('2d'),values=points.map(p=>p.cumulative_value_per_100),min=Math.min(...values),max=Math.max(...values),span=max-min||1,w=c.width-70,h=c.height-60;x.clearRect(0,0,c.width,c.height);x.strokeStyle='#1d467a';x.lineWidth=2;x.beginPath();points.forEach((p,i)=>{const px=45+i/Math.max(points.length-1,1)*w,py=20+(max-p.cumulative_value_per_100)/span*h;i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke()}

// Pricing-page usability enhancements are kept together so the authoritative
// pricing definitions still come from the service rather than duplicated HTML.
const renderOtcProductEditorBase=renderOtcProductEditor;
renderOtcProductEditor=function(p){renderOtcProductEditorBase(p);if(!p.id||p.structure!=='classic_snowball')return;const actions=document.querySelector('#otcProductForm .otc-editor-actions'),audit=document.getElementById('otcFieldAuditButton');if(!actions||actions.querySelector('[data-otc-price-product]'))return;const button=document.createElement('button');button.type='button';button.dataset.otcPriceProduct='1';button.textContent='复制到期权定价';button.onclick=priceOtcProduct;actions.insertBefore(button,audit||actions.lastElementChild)};

function priceOtcProduct(){if(!otcState.product||otcState.product.structure!=='classic_snowball')return;otcState.pricingSourceId=otcState.product.id;closeOtcProductDrawer();dashGo('otc-derivatives',false,'pricing')}

function syncOtcPricingTerm(form){if(!form)return;const term=Number(form.elements.term_months.value||0);['lock_period_months','coupon_switch_months'].forEach(name=>{const input=form.elements[name];if(!input)return;input.max=String(term);if(Number(input.value)>term)input.value=String(term)})}

otcPricingInput=function(def,value){const optional=def.default==null,maximum=def.max_from?'':(def.max==null?'':`max="${def.max}"`),minimum=def.min_exclusive!=null?'min="0.000001"':(def.min==null?'':`min="${def.min}"`),change=def.name==='term_months'?'onchange="syncOtcPricingTerm(this.form)" oninput="syncOtcPricingTerm(this.form)"':'';return`<label>${escapeHtml(def.label)}<input name="${def.name}" type="number" ${minimum} ${maximum} step="${def.step||'any'}" value="${value==null?'':value}" ${optional?'':'required'} ${change}></label>`};

otcPricingReferencesHtml=function(refs){const rows=(refs&&refs.indices)||[];return rows.map(index=>`<article class="otc-reference"><b>${escapeHtml(index.name)} <small>${escapeHtml(index.as_of||'无数据')}</small></b><div>${Object.entries(index.volatility||{}).map(([window,value])=>`<button ${value==null?'disabled':''} onclick="useOtcPricingReference('volatility',${value==null?'null':value})">${window}日波动 ${value==null?'—':otcPercent(value)}</button>`).join('')}</div><div>${(index.basis||[]).map(x=>`<span class="otc-reference-set"><small>${escapeHtml(x.tenor)}</small>${[['最新',x.latest],['20日',x.mean_20],['60日',x.mean_60]].map(item=>`<button ${item[1]==null?'disabled':''} onclick="useOtcPricingReference('basis_rate',${item[1]==null?'null':item[1]})">${item[0]} ${item[1]==null?'—':otcPercent(item[1])}</button>`).join('')}</span>`).join('')}</div></article>`).join('')+((refs||{}).discount_rate&&refs.discount_rate.available?`<article class="otc-reference"><b>中国10年期国债 <small>${escapeHtml(refs.discount_rate.as_of||'')}</small></b><button onclick="useOtcPricingReference('discount_rate',${refs.discount_rate.value})">填入 ${otcPercent(refs.discount_rate.value)}</button></article>`:'<p>贴现率参考不可用</p>')};

const copyOtcPricingProductBase=copyOtcPricingProduct;
copyOtcPricingProduct=function(id){copyOtcPricingProductBase(id);syncOtcPricingTerm(document.getElementById('otcPricingForm'))};

const loadOtcPricingPageBase=loadOtcPricingPage;
loadOtcPricingPage=async function(host){await loadOtcPricingPageBase(host);const form=document.getElementById('otcPricingForm');syncOtcPricingTerm(form);if(otcState.pricingSourceId&&form){const picker=document.getElementById('otcPricingProduct');if(picker)picker.value=otcState.pricingSourceId;copyOtcPricingProduct(otcState.pricingSourceId);otcState.pricingSourceId=null}};

const loadOtcPricingRunBase=loadOtcPricingRun;
loadOtcPricingRun=async function(id){await loadOtcPricingRunBase(id);const button=document.getElementById('otcPricingButton'),message=document.getElementById('otcPricingMessage'),result=document.querySelector('#otcPricingResult .otc-result-head');if(button)button.disabled=false;if(message&&result){message.textContent='定价完成，可调整参数后再次试算';message.classList.remove('error')}};
